#!/usr/bin/env bash
# Encode a video on the job's NVIDIA GPU (NVENC) and on the CPU, and compare. The source clip
# is generated by ffmpeg, so nothing is downloaded. Needs ffmpeg built with NVENC on the worker
# (Ubuntu's ffmpeg package is); the NVENC library comes with the NVIDIA driver.
#
#   transcode.sh [SECONDS] [WIDTHxHEIGHT]
set -euo pipefail
secs=${1:-20} size=${2:-1920x1080}
out=${GPULAYER_OUTPUT_DIR:-out}
mkdir -p "$out"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
ffmpeg -hide_banner -loglevel error -f lavfi -i "testsrc2=size=$size:rate=30:duration=$secs" \
  -c:v ffv1 "$work/source.mkv"
ffmpeg -hide_banner -encoders 2>/dev/null | grep -q h264_nvenc \
  || { echo "this ffmpeg has no h264_nvenc encoder" >&2; exit 1; }
enc() {  # enc NAME ARGS...
  local name=$1; shift
  local t0 t1
  t0=$(date +%s.%N)
  ffmpeg -hide_banner -loglevel error -y -i "$work/source.mkv" "$@" "$out/$name.mp4"
  t1=$(date +%s.%N)
  printf 'ENCODE %-6s %6.2fs  %s\n' "$name" "$(echo "$t1 - $t0" | bc)" "$(du -h "$out/$name.mp4" | cut -f1)"
}
echo "$((secs * 30)) frames at $size on $(hostname)"
enc nvenc -c:v h264_nvenc -preset p4 -b:v 8M
enc x264 -c:v libx264 -preset medium -b:v 8M
